import 'dotenv/config';

interface RecaptchaVerifyResponse {
  success: boolean;
  challenge_ts?: string;
  hostname?: string;
  'error-codes'?: string[];
}

/**
 * Function that takes a provided client-side reCAPTCHA code and verifies it with Google
 *
 * @param token The token generated by Google reCAPTCHA from the client side verification
 * @returns A promise indicating whether the backend's verification was successful or not
 */
export default async function verifyCaptcha(token: string): Promise<boolean> {
  const RECAPTCHA_SECRET_KEY = process?.env?.['RECAPTCHA_V2_SECRET_KEY'];

  if (!RECAPTCHA_SECRET_KEY) {
    throw new Error('Error: ReCaptcha secret key not found in env');
  }

  const GOOGLE_CAPTCHA_VERIFICATION_URL =
    'https://www.google.com/recaptcha/api/siteverify';

  // Send an API request to Google reCAPTCHA and verify the provided token code
  const response = await fetch(GOOGLE_CAPTCHA_VERIFICATION_URL, {
    method: 'POST',
    headers: {
      'Content-type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({
      secret: RECAPTCHA_SECRET_KEY,
      response: token,
    }),
    signal: AbortSignal.timeout(5000),
  });

  // If the response failed, then the verification has failed too
  if (!response.ok) {
    throw new Error('Error: Google reCAPTCHA verification request failed!');
  }

  const result = (await response.json()) as RecaptchaVerifyResponse;

  return result.success === true;
}
